const { chromium } = require('/tmp/utktest/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({
    args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader',
           '--ignore-gpu-blocklist', '--enable-webgl'],
  });
  const page = await browser.newPage({ viewport: { width: 1200, height: 900 } });
  const logs = [];
  page.on('console', m => logs.push('[console.' + m.type() + '] ' + m.text()));
  page.on('pageerror', e => logs.push('[pageerror] ' + e.message));

  await page.goto('http://localhost:5001/', { waitUntil: 'networkidle', timeout: 60000 }).catch(e => logs.push('[goto] ' + e.message));
  // give WebGL time to load big buildings layer + render
  await page.waitForTimeout(25000);

  // sample the map canvas pixels
  const result = await page.evaluate(() => {
    const canvases = [...document.querySelectorAll('canvas')];
    const out = [];
    for (const c of canvases) {
      try {
        const gl = c.getContext('webgl2') || c.getContext('webgl');
        const w = c.width, h = c.height;
        if (!w || !h) { out.push({ w, h, note: 'zero-size' }); continue; }
        // read a grid of pixels
        const pts = [];
        const gx = 6, gy = 6;
        for (let i = 1; i < gx; i++) for (let j = 1; j < gy; j++) {
          const px = Math.floor(w * i / gx), py = Math.floor(h * j / gy);
          const buf = new Uint8Array(4);
          if (gl) { gl.readPixels(px, h - py, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, buf); }
          pts.push([buf[0], buf[1], buf[2]]);
        }
        // histogram of colors
        const hist = {};
        for (const p of pts) { const k = p.join(','); hist[k] = (hist[k] || 0) + 1; }
        out.push({ w, h, hasGL: !!gl, samples: pts.length, hist });
      } catch (e) { out.push({ err: String(e) }); }
    }
    return out;
  });

  console.log('=== CANVAS PIXEL ANALYSIS ===');
  console.log(JSON.stringify(result, null, 1));
  await page.screenshot({ path: '/tmp/utktest/shot.png' }).catch(() => {});
  console.log('\n=== PAGE LOGS (last 40) ===');
  console.log(logs.slice(-40).join('\n'));
  await browser.close();
})();

