}
const cands=['interpolateInferno','interpolateViridis','interpolateReds','interpolateOranges','interpolateYlOrRd','interpolateYlGnBu','interpolateRdYlBu','interpolateCividis','interpolatePuRd','interpolateBuPu','interpolateGnBu'];
