const { chromium } = require('/tmp/utktest/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({
    args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader',
           '--ignore-gpu-blocklist', '--enable-webgl'],
  });
  const page = await browser.newPage({ viewport: { width: 1200, height: 900 } });
  const logs = [];
  page.on('console', m => logs.push('[' + m.type() + '] ' + m.text()));
  page.on('pageerror', e => logs.push('[pageerror] ' + e.message));

  await page.goto('http://localhost:5001/', { waitUntil: 'networkidle', timeout: 60000 }).catch(e => logs.push('[goto] ' + e.message));
  await page.waitForTimeout(25000);

  const result = await page.evaluate(() => {
    const c = [...document.querySelectorAll('canvas')].sort((a,b)=>b.width*b.height-a.width*a.height)[0];
    const gl = c.getContext('webgl2') || c.getContext('webgl');
    const w = c.width, h = c.height;
    // dense grid sample
    const buf = new Uint8Array(w * h * 4);
    gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, buf);
    const hist = {};
    let red = 0, total = 0;
    const step = 4; // sample every 4px
    for (let y = 0; y < h; y += step) for (let x = 0; x < w; x += step) {
      const i = (y * w + x) * 4;
      const r = buf[i], g = buf[i+1], b = buf[i+2], a = buf[i+3];
      if (a === 0) continue;
      total++;
      // bucket to nearest 16 for histogram
      const key = [r,g,b].map(v=>Math.round(v/16)*16).join(',');
      hist[key] = (hist[key]||0)+1;
      // "pure red" = high R, low G, low B (the old default interpolateReds bug signature)
      if (r > 180 && g < 90 && b < 90) red++;
    }
    const top = Object.entries(hist).sort((a,b)=>b[1]-a[1]).slice(0,15);
    // count distinct YlOrRd-ish building shades (yellow->orange->red): R high, G mid-high->low
    return { w, h, total, pureRedPct: (100*red/total).toFixed(1), distinctColors: Object.keys(hist).length, top };
  });

  console.log('=== canvas', result.w+'x'+result.h, 'sampled', result.total, 'px ===');
  console.log('pure-red %:', result.pureRedPct, '| distinct color buckets:', result.distinctColors);
  console.log('top colors (r,g,b : count):');
  for (const [k,v] of result.top) console.log('  ', k, ':', v);
  const errs = logs.filter(l => /error|not big enough|INVALID/i.test(l));
  console.log('\n=== GL/errors in console ===');
  console.log(errs.length ? errs.join('\n') : 'none');
  await browser.close();
})();

